            <a href="#contact" onClick={() => setIsMobileMenuOpen(false)} style={{ display: 'block', width: '100%', padding: '1rem', background: '#3b82f6', color: 'white', textAlign: 'center', borderRadius: '0.5rem', fontWeight: 600, fontSize: '1.1rem' }}>
